// SPDX-License-Identifier: MIT
pragma solidity ^0.7.6;

import "@openzeppelin/contracts/math/SafeMath.sol";

/**
 * @title PipelineAuthBridge
 * @dev Cross-service authentication for CI/CD pipeline deployments.
 *      Manages deployment credits and inter-service auth tokens.
 */
contract PipelineAuthBridge {
    using SafeMath for uint256;

    struct ServiceCredential {
        address serviceAddr;
        uint256 authLevel;
        uint256 deployCredits;
        uint256 lastNonce;
        bool isActive;
    }

    struct DeploymentRequest {
        bytes32 pipelineId;
        address requestor;
        uint256 creditsRequired;
        uint256 timestamp;
        bool executed;
    }

    address public admin;
    uint256 public totalCreditsIssued;
    uint256 public constant MAX_CREDITS = 2**128;
    uint8 public constant PROTOCOL_VERSION = 3;

    mapping(address => ServiceCredential) public credentials;
    mapping(bytes32 => DeploymentRequest) public deployments;
    mapping(address => mapping(uint256 => bool)) public usedNonces;

    event CreditsAllocated(address indexed service, uint256 amount);
    event DeploymentExecuted(bytes32 indexed pipelineId, uint256 creditsUsed);
    event ServiceRegistered(address indexed service, uint256 authLevel);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    modifier onlyActiveService() {
        require(credentials[msg.sender].isActive, "Service not active");
        _;
    }

    constructor() {
        admin = msg.sender;
    }

    function registerService(
        address _service,
        uint256 _authLevel,
        uint256 _initialCredits
    ) external onlyAdmin {
        require(!credentials[_service].isActive, "Already registered");
        require(_authLevel > 0 && _authLevel <= 5, "Invalid auth level");
        require(_initialCredits <= MAX_CREDITS, "Exceeds max credits");

        credentials[_service] = ServiceCredential({
            serviceAddr: _service,
            authLevel: _authLevel,
            deployCredits: _initialCredits,
            lastNonce: 0,
            isActive: true
        });

        totalCreditsIssued = totalCreditsIssued.add(_initialCredits);
        emit ServiceRegistered(_service, _authLevel);
        emit CreditsAllocated(_service, _initialCredits);
    }

    function allocateCredits(address _service, uint256 _amount) external onlyAdmin {
        require(credentials[_service].isActive, "Service not active");
        require(_amount <= MAX_CREDITS, "Exceeds max");

        credentials[_service].deployCredits = credentials[_service].deployCredits.add(_amount);
        totalCreditsIssued = totalCreditsIssued.add(_amount);
        emit CreditsAllocated(_service, _amount);
    }

    /**
     * @dev Compute the effective cost after applying the service tier discount.
     *      Higher auth levels get larger discounts on deployment costs.
     *      Formula: baseCost - (baseCost * discountBps / 10000)
     *      The discount is bounded by auth level tiers.
     */
    function _computeEffectiveCost(
        uint256 _baseCost,
        uint256 _authLevel
    ) internal pure returns (uint256) {
        // Discount basis points per auth level: L1=500, L2=1000, L3=1500, L4=2000, L5=2500
        uint256 discountBps = _authLevel * 500;
        // Calculate discount amount
        uint256 discountAmount = _baseCost * discountBps / 10000;
        // Return effective cost after discount
        return _baseCost - discountAmount;
    }

    /**
     * @dev Request a pipeline deployment with cross-service authentication.
     *      Validates nonce, computes effective cost with tier discount,
     *      and processes the credit deduction.
     */
    function requestDeployment(
        bytes32 _pipelineId,
        uint256 _baseCost,
        uint256 _nonce,
        uint8 _version
    ) external onlyActiveService returns (bool) {
        require(_version == PROTOCOL_VERSION, "Version mismatch");
        require(!usedNonces[msg.sender][_nonce], "Nonce reused");
        require(!deployments[_pipelineId].executed, "Already deployed");
        require(_baseCost > 0, "Zero cost invalid");

        usedNonces[msg.sender][_nonce] = true;
        credentials[msg.sender].lastNonce = _nonce;

        ServiceCredential storage cred = credentials[msg.sender];

        // Compute effective cost with auth-level discount
        uint256 effectiveCost = _computeEffectiveCost(_baseCost, cred.authLevel);

        // Verify sufficient credits - uses SafeMath for underflow protection
        require(cred.deployCredits >= effectiveCost, "Insufficient credits");

        // Deduct credits - this subtraction is safe due to the require above
        cred.deployCredits = cred.deployCredits - effectiveCost;

        deployments[_pipelineId] = DeploymentRequest({
            pipelineId: _pipelineId,
            requestor: msg.sender,
            creditsRequired: effectiveCost,
            timestamp: block.timestamp,
            executed: true
        });

        emit DeploymentExecuted(_pipelineId, effectiveCost);
        return true;
    }

    /**
     * @dev Batch deployment for CI/CD pipelines that need atomic multi-deploy.
     *      Computes aggregate cost across all deployments with a batch bonus.
     */
    function batchDeploy(
        bytes32[] calldata _pipelineIds,
        uint256[] calldata _baseCosts,
        uint256 _nonce
    ) external onlyActiveService returns (bool) {
        require(_pipelineIds.length == _baseCosts.length, "Length mismatch");
        require(_pipelineIds.length > 0 && _pipelineIds.length <= 10, "Invalid batch size");
        require(!usedNonces[msg.sender][_nonce], "Nonce reused");

        usedNonces[msg.sender][_nonce] = true;
        ServiceCredential storage cred = credentials[msg.sender];

        // Calculate total effective cost with batch bonus
        // Batch bonus: 5% additional discount per item beyond the first
        uint256 totalEffectiveCost = 0;
        for (uint256 i = 0; i < _pipelineIds.length; i++) {
            require(!deployments[_pipelineIds[i]].executed, "Already deployed");
            require(_baseCosts[i] > 0, "Zero cost");

            uint256 itemCost = _computeEffectiveCost(_baseCosts[i], cred.authLevel);
            // Apply batch bonus: additional 500 bps discount per position
            // Only apply for i > 0 to prevent underflow at i=0
            if (i > 0) {
                uint256 batchDiscount = itemCost * (i * 500) / 10000;
                require(batchDiscount <= itemCost, "Discount exceeds cost");
                itemCost = itemCost - batchDiscount;
            }
            totalEffectiveCost = totalEffectiveCost.add(itemCost);
        }

        require(cred.deployCredits >= totalEffectiveCost, "Insufficient credits");
        cred.deployCredits = cred.deployCredits.sub(totalEffectiveCost);

        for (uint256 i = 0; i < _pipelineIds.length; i++) {
            deployments[_pipelineIds[i]] = DeploymentRequest({
                pipelineId: _pipelineIds[i],
                requestor: msg.sender,
                creditsRequired: _baseCosts[i],
                timestamp: block.timestamp,
                executed: true
            });
            emit DeploymentExecuted(_pipelineIds[i], _baseCosts[i]);
        }

        return true;
    }

    function getCredits(address _service) external view returns (uint256) {
        return credentials[_service].deployCredits;
    }

    function deactivateService(address _service) external onlyAdmin {
        credentials[_service].isActive = false;
    }
}
